"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["16599"],{74570(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_derivacao_fato.ordem_regra_duplicada","status":422,"titulo":"Duas regras da mesma deriva\xe7\xe3o t\xeam a mesma ordem"},"descricao":{"codigo":"uniplus.selecao.configuracao_derivacao_fato.ordem_regra_duplicada","requisitos":[],"oQueAconteceu":["Na defini\xe7\xe3o das regras de deriva\xe7\xe3o do processo, duas ou mais regras da mesma configura\xe7\xe3o\\nt\xeam o mesmo valor de `ordem`. A ordem posiciona cada regra na configura\xe7\xe3o e precisa ser \xfanica\\ndentro dela; a mesma ordem pode se repetir em configura\xe7\xf5es de fatos diferentes.","A recusa vem no campo `configuracoes[i].regras` e faz parte da confer\xeancia de forma, que\\nacumula no array `errors[]` todas as viola\xe7\xf5es de todas as configura\xe7\xf5es e regras do pedido\\nantes de consultar o cat\xe1logo de fatos. A mensagem n\xe3o informa qual ordem se repete nem o\\nc\xf3digo do fato.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na defini\xe7\xe3o das regras, d\xea a cada regra da configura\xe7\xe3o um valor de `ordem` pr\xf3prio, n\xe3o\\nnegativo.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de regras de deriva\xe7\xe3o de fatos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao derivacao fato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);